[12 Regression] template keyword incorrectly required to access template class static member of non-dependent expression using member syntax in dependent context
Clang accepts the following, gcc thinks the expression in the line marked "HERE" should be `tag<int>.template smbr<void>`.

    template <class T>
    struct tag_t {
      template <class Sig>
      static constexpr const Sig* smbr = nullptr; 
      int i = 0;
    };

    template <class T>
    inline constexpr tag_t<T> tag {};

    // This is OK
    using X = decltype(tag<int>.smbr<void>);

    template <class U>
    struct S {
      // This is incorrectly rejected by gcc
      using Y = decltype(tag<int>.smbr<void>);

      // This is OK
      using Z = decltype(tag_t<int>::smbr<void>);
    };https://godbolt.org/z/9GoPYTYa1
